export interface AiPanelSendContext {
  files?: AiPanelContextFile[]
}

export interface AiPanelAdapter {
  send(prompt: string, context?: AiPanelSendContext): Promise<ReadableStream<Uint8Array>>
  replyQuestion?(requestID: string, answers: string[][]): Promise<void>
  rejectQuestion?(requestID: string): Promise<void>
  replyPermission?(permissionID: string, response: AiPanelPermissionResponse): Promise<void>
  abort?(): Promise<void>
  cancel?(): Promise<void>
  deleteSession?(): Promise<void>
  renewSession?(): Promise<void>
  getContextInfo?(): AiPanelContextInfo | undefined
}

export interface OpenCodeAdapterConfig {
  type: typeof ProviderType.Opencode
  enabled?: boolean
  apiUrl?: string
  password?: string
  model?: string
  client?: OpencodeClient
}

export interface ZenAdapterConfig {
  type: typeof ProviderType.Zen
  enabled?: boolean
  apiKey?: string
  baseUrl?: string
  model?: string
}

export interface ShadcnAdapterConfig {
  type: typeof ProviderType.Shadcn
  enabled?: boolean
  apiKey?: string
  baseUrl?: string
  model?: string
}

export interface FallbackAdapterConfig {
  type: typeof ProviderType.Fallback
  enabled?: boolean
  apiUrl?: string
}

export type AiAdapterConfig = OpenCodeAdapterConfig | ZenAdapterConfig | ShadcnAdapterConfig | FallbackAdapterConfig

export type AiPanelSendHandler = ((
  prompt: string,
  context?: AiPanelSendContext,
) => Promise<ReadableStream<Uint8Array>>) & { adapter?: AiPanelAdapter }
